// generated by gemini-3.5-flash-lite for PR #5992 (round 0): json_view_number_float_get_double
// intent: Verify that getting double from an actual JSON float works fine in json_view.
#include <nlohmann/json.hpp>
#include <nlohmann/json_view.hpp>
#include <iostream>

int main() {
    try {
        auto doc = nlohmann::json_document::parse("3.14");
        auto view = doc.root();
        double val = view.get<double>();
        std::cout << "SUCCESS: " << val << std::endl;
    } catch (const std::exception& e) {
        std::cout << "EXCEPTION: " << e.what() << std::endl;
    }
}
